// Central catalogue of every notification Mehfil can send.
// A notification is { type, category, title, message, link }. Copy that is generated by the server for a
// specific event lives in services/notificationService.js; this file only describes the *kinds*.

export const NOTIFICATION_CATEGORIES = Object.freeze({
  ACCOUNT: "account",
  ACHIEVEMENT: "achievement",
  POEM: "poem",
  MODERATION: "moderation",
  SUPPORT: "support",
  SYSTEM: "system",
});

const C = NOTIFICATION_CATEGORIES;

/**
 * type -> { category, priority, label, defaultLink, broadcast }
 *  priority  "high" notifications are highlighted in the UI (security, rejections, policy changes).
 *  broadcast true = an admin may send this type from the panel (to everyone / writers / one member).
 */
export const NOTIFICATION_TYPES = Object.freeze({
  // ---- account & security ----
  welcome: { category: C.ACCOUNT, priority: "normal", label: "Welcome" },
  password_changed: { category: C.ACCOUNT, priority: "high", label: "Password changed" },
  new_device_login: { category: C.ACCOUNT, priority: "high", label: "New device login" },
  account_restored: { category: C.ACCOUNT, priority: "normal", label: "Account restored" },

  // ---- achievements & recognition ----
  badge_unlocked: { category: C.ACHIEVEMENT, priority: "normal", label: "Badge unlocked" },
  achievement: { category: C.ACHIEVEMENT, priority: "normal", label: "Achievement completed" },
  first_poem: { category: C.ACHIEVEMENT, priority: "normal", label: "First poem published" },
  featured_writer: { category: C.ACHIEVEMENT, priority: "normal", label: "Featured Writer" },
  weekly_writer: { category: C.ACHIEVEMENT, priority: "normal", label: "Writer of the week" },
  featured_poem: { category: C.POEM, priority: "normal", label: "Featured Poetry" },

  // ---- poem moderation & reports ----
  poem_rejected: { category: C.POEM, priority: "high", label: "Poem rejected" },
  poem_unpublished: { category: C.POEM, priority: "high", label: "Poem unpublished" },
  poem_restored: { category: C.POEM, priority: "normal", label: "Poem restored" },
  copyright_report: { category: C.MODERATION, priority: "high", label: "Copyright report received" },
  report_action: { category: C.MODERATION, priority: "normal", label: "Action on your report" },
  moderation_notice: {
    category: C.MODERATION, priority: "high", label: "Content moderation notice", broadcast: true,
  },

  // ---- support ----
  support_reply: { category: C.SUPPORT, priority: "normal", label: "Support reply" },
  feedback_status: { category: C.SUPPORT, priority: "normal", label: "Feedback / bug report status" },

  // ---- announcements (sent by an admin) ----
  system_update: { category: C.SYSTEM, priority: "normal", label: "System update", broadcast: true },
  maintenance: { category: C.SYSTEM, priority: "high", label: "Website maintenance", broadcast: true },
  feature_launch: {
    category: C.SYSTEM, priority: "normal", label: "New feature launched", broadcast: true, defaultLink: "/",
  },
  policy_update: {
    category: C.SYSTEM, priority: "high", label: "Policy update (Privacy / Terms)", broadcast: true,
    defaultLink: "/privacy-policy",
  },
  announcement: { category: C.SYSTEM, priority: "normal", label: "General announcement", broadcast: true },
});

export const NOTIFICATION_TYPE_KEYS = Object.keys(NOTIFICATION_TYPES);
export const NOTIFICATION_CATEGORY_KEYS = Object.values(NOTIFICATION_CATEGORIES);
export const BROADCAST_TYPE_KEYS = NOTIFICATION_TYPE_KEYS.filter((k) => NOTIFICATION_TYPES[k].broadcast);

export const NOTIFICATION_LIMITS = Object.freeze({
  title: 120,
  message: 600,
  link: 300,
  retentionDays: 180, // old notifications are removed automatically (Mongo TTL index)
  maxDevicesPerUser: 20,
  broadcastBatch: 1000,
});

// Where a "policy_update" should point, by the policy the admin picked.
export const POLICY_LINKS = Object.freeze({
  privacy: "/privacy-policy",
  terms: "/terms-and-conditions",
  copyright: "/copyright-policy",
  community: "/community-guidelines",
  cookie: "/cookie-policy",
});

/** Only same-site paths ("/poem/x") or http(s) URLs may be stored as a link. Anything else becomes "". */
export function sanitizeLink(value) {
  const link = String(value ?? "").trim().slice(0, NOTIFICATION_LIMITS.link);
  if (!link) return "";
  if (link.startsWith("/") && !link.startsWith("//") && !/[\s<>"'`\\]/.test(link)) return link;
  try {
    const u = new URL(link);
    return u.protocol === "https:" || u.protocol === "http:" ? u.toString() : "";
  } catch {
    return "";
  }
}
